/bin/bash -lc "node --input-type=module <<'JS'
import {chromium} from '/home/node/.npm/_npx/420ff84f11983ee5/node_modules/playwright/index.mjs';
const browser = await chromium.launch({headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1000},deviceScaleFactor:1});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:5173/', {waitUntil:'networkidle'});
await page.screenshot({path:'/tmp/prostor-desktop.png',fullPage:true});
console.log(JSON.stringify({errors,title:await page.title(),width:await page.evaluate(()=>document.documentElement.scrollWidth),image:await page.locator('.welcome-photo img').evaluate(img=>img.complete&&img.naturalWidth>0)}));
await browser.close();
JS"

