args.command:
/bin/bash -lc "node --input-type=module <<'JS'
import fs from 'node:fs';
const response=await fetch('https://fonts.googleapis.com/css2?family=Golos+Text:wght@400..800&display=swap',{headers:{'User-Agent':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/132.0.0.0 Safari/537.36'}});
let css=await response.text();const urls=[...new Set(css.match(/https:\\/\\/["'^)]+/g))];
fs.mkdirSync('"'public/fonts',{recursive:true});
for(let i=0;i<urls.length;i++){const r=await fetch(urls[i]);if("'!r.ok)throw new Error('"'Font request failed');const name='golos-'+i+(urls[i].includes('.woff2')?'.woff2':'.ttf');fs.writeFileSync('public/fonts/'+name,Buffer.from(await r.arrayBuffer()));css=css.replaceAll(urls[i],'/fonts/'+name);}
fs.writeFileSync('public/fonts/golos.css',css);console.log('Saved '+urls.length+' local font assets');
JS"

